def transform(grid):
    """Turn full-width and full-height separator lines into color 2."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        if all(v == row[0] for v in row):
            out[r] = [2] * w
    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)):
            for r in range(h):
                out[r][c] = 2
    return out

